// a set by its id ({ id, name, group, colors }), or null
function colorSet(id) {
  for (const r of COLORSETS) if (r[0] === id) return { id: r[0], name: r[1], group: r[2], colors: r[3].slice() };
  return null;
}
// every set of a group (or all of them), in order
function colorSetsIn(group) {
  return COLORSETS.filter(function (r) { return !group || r[2] === group; }).map(function (r) { return { id: r[0], name: r[1], group: r[2], colors: r[3].slice() }; });
}
